// Pre-rendered, byte-identical official Willena PNG icons. No CPU-heavy
// on-request vector rasterization; Chrome installability needs fast valid icons.
const ICONS={
 '192.png':'',
 '512.png':''
};
const cache=new Map();
export async function onRequest({request}){
 const name=new URL(request.url).pathname.split('/').pop();
 const encoded=ICONS[name];
 if(!encoded)return new Response('Not found',{status:404});
 let bytes=cache.get(name);
 if(!bytes){
  const binary=atob(encoded);
  bytes=new Uint8Array(binary.length);
  for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);
  cache.set(name,bytes);
 }
 return new Response(bytes,{headers:{'content-type':'image/png','cache-control':'public, max-age=86400','x-content-type-options':'nosniff'}});
}
